import type { RootState } from '../../store'
import { createSelector, createSlice } from '@reduxjs/toolkit'
import { fetchSkills, updateSkill } from './thunks'

interface ISkill {
  id: string
  name: string
}

export interface ICategory {
  id: string
  name: string
  parent: string | null
  children: ISkill[]
}

interface SkillsState {
  categories: ICategory[]
  status: 'idle' | 'loading' | 'succeeded' | 'failed'
  error: string | null
}

const initialState: SkillsState = {
  categories: [],
  status: 'idle',
  error: null,
}

export const skillsSlice = createSlice({
  name: 'skills',
  initialState,
  reducers: {
    clearSkills: (state) => {
      state.categories = []
      state.status = 'idle'
      state.error = null
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchSkills.fulfilled, (state, action) => {
        state.status = 'succeeded'
        state.categories = action.payload
      })
      .addCase(fetchSkills.pending, (state) => {
        state.status = 'loading'
        state.error = null
      })
      .addCase(fetchSkills.rejected, (state, action) => {
        state.status = 'failed'
        state.error = action.payload as string
      })
      .addCase(updateSkill.fulfilled, (state, action) => {
        const { categoryId, skillId, newName } = action.payload
        const category = state.categories.find(c => c.id === categoryId)
        if (category) {
          const skill = category.children.find(s => s.id === skillId)
          if (skill)
            skill.name = newName
        }
      })
  },
})

export const selectAllCategories = (state: RootState) => state.skills.categories
export const selectSkillsStatus = (state: RootState) => state.skills.status
export const selectSkillsError = (state: RootState) => state.skills.error

export function selectCategoryById(categoryId: string) {
  return createSelector(selectAllCategories, categories =>
    categories.find(category => category.id === categoryId))
}

export function selectSkillById(skillId: string) {
  return createSelector(selectAllCategories, (categories) => {
    for (const category of categories) {
      const skill = category.children.find(s => s.id === skillId)
      if (skill)
        return skill
    }
    return null
  })
}

export const { clearSkills } = skillsSlice.actions
export default skillsSlice.reducer
